config.source:
import json

def main(state):
    raw = state.get('review', '')
    start, end = raw.find('{'), raw.rfind('}')
    try:
        data = json.loads(raw[start:end + 1])
    except Exception:
        data = {'score': 0, 'critique': 'unparseable review'}
    rounds = int(state.get('rounds', 0)) + 1
    return {'score': int(data.get('score', 0)), 'critique': str(data.get('critique', '')), 'rounds': rounds}
